"""
Return the shadow matrix of the source's Methods E for the orthonormal operator basis K (rows are Pauli-basis coefficient vectors on M sites): the matrix of the Liouvillian L[O] = i [H, O] in that basis under the inner product <A, B> = Tr(A^dagger B) / 2^M, with the row index labelling the basis vector against which L applied to the column vector is projected. Raise ValueError if K is not a (K, 4^M) array. Pauli strings are encoded as in step 1: code = sum_s f_s 4^s with f_s = 0, 1, 2, 3 for I, X, Z, Y on site s = 0..M-1, site 1 being the least significant digit s = 0.

Restricted to the pruned operator basis, the Heisenberg generator becomes a small matrix that propagates the vector of expectation values of the basis operators.

Returns
-------
ndarray of float64 with shape (K, K).
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

import numpy as np


def shadow_matrix(terms, M, K):
    """ndarray of float64 with shape (K, K)."""
    return np.zeros((np.shape(K)[0], np.shape(K)[0]), dtype=np.float64)

# =============================================================================
# GOLD SOLUTION
# =============================================================================

import numpy as np


def _oracle_shadow_matrix(terms, M, K):
    """Shadow matrix A_ij = <K_i, L K_j> with L[O] = i[H, O] (Methods E of the source);
    A is real antisymmetric for an orthonormal basis."""
    K = np.asarray(K, dtype=np.float64)
    M = int(M)
    if K.ndim != 2 or K.shape[1] != 4 ** M:
        raise ValueError("K must be (n_vectors, 4^M)")
    n = K.shape[0]
    A = np.zeros((n, n), dtype=np.float64)
    for j in range(n):
        LK = _oracle_liouvillian_apply(terms, M, K[j])
        A[:, j] = K @ LK
    return A

